<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Interview;use App\Models\Job;use App\Models\JobApplication;use App\Models\TalentInvitation;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class NotificationsAndCalendarTest extends TestCase{use RefreshDatabase;public function test_invitation_creates_internal_notification_and_preferences_require_consent():void{$candidate=User::factory()->create(['account_type'=>'candidate']);$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'slug'=>'job','title'=>'Developer','summary'=>'Job','location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active']);TalentInvitation::create(['company_id'=>$company->id,'job_id'=>$job->id,'candidate_user_id'=>$candidate->id,'sent_by'=>$owner->id]);$this->assertDatabaseHas('in_app_notifications',['user_id'=>$candidate->id,'type'=>'talent_invitation']);$this->actingAs($candidate,'sanctum')->putJson('/api/v1/notifications/preferences',['email_enabled'=>true,'push_enabled'=>false,'whatsapp_enabled'=>true])->assertOk();$this->assertDatabaseMissing('notification_preferences',['user_id'=>$candidate->id,'whatsapp_consented_at'=>null]);}public function test_candidate_can_export_own_interview_calendar():void{$candidate=User::factory()->create(['account_type'=>'candidate']);$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'slug'=>'job','title'=>'Developer','summary'=>'Job','location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active']);$application=JobApplication::create(['job_id'=>$job->id,'user_id'=>$candidate->id,'status'=>'interview','profile_snapshot'=>[],'applied_at'=>now()]);$interview=Interview::create(['job_application_id'=>$application->id,'created_by'=>$owner->id,'title'=>'Entrevista','scheduled_at'=>now()->addDay(),'duration_minutes'=>30,'format'=>'video']);$this->actingAs($candidate,'sanctum')->get("/api/v1/interviews/{$interview->id}/calendar")->assertOk()->assertHeader('Content-Type','text/calendar; charset=utf-8')->assertSee('BEGIN:VCALENDAR');}}
